	name	Sort by file name
	none	Do not sort (-U)
	time	Sort by time (-t)
	size	Sort by size (-S)
	version	Sort by version numbers
	extension	Sort by extension (-X)
	width	Sort by width
ARGCEOF
}

_static_indicator_style() {
